body_script:
document.addEventListener('DOMContentLoaded',function(){try{
  var msel=document.getElementById('c-model');
  if(msel){
    msel.addEventListener('change',function(){
      var v=parseFloat(msel.value);
      var cap=document.getElementById('c-cap');
      if(v>0&&cap){cap.value=v;if(typeof calcR==='function')calcR();}
    });
  }
  var cons=document.getElementById('c-cons');
  if(cons&&!document.getElementById('c-cons-hint')){
    var h=document.createElement('div');
    h.id='c-cons-hint';
    h.style.cssText='font-size:12px;color:var(--txt-muted);margin-top:4px';
    h.textContent='Типично для китайских EV: 14–19 кВт·ч/100 км. Точную цифру смотрите в характеристиках вашей модели.';
    cons.parentNode.insertBefore(h,cons.nextSibling);
  }
}catch(e){}});

document.addEventListener('DOMContentLoaded',function(){try{
  // дельта EV vs бензин (крупный блок под результатом)
  var out=document.getElementById('c-out');
  if(out){
    var dv=document.createElement('div');dv.id='c-delta-wrap';dv.style.display='none';
    out.parentNode.insertBefore(dv,out.nextSibling);
    function money(txt){var m=String(txt).replace(/\s/g,'').match(/(-?\d+[\d,\.]*)/);return m?parseFloat(m[1].replace(',','.')):NaN}
    function upd(){
      try{
        var cons=parseFloat(document.getElementById('c-cons').value)||0;
        var km=parseFloat(document.getElementById('c-km').value)||0;
        var sel=document.getElementById('c-scene');
        var custom=parseFloat(document.getElementById('c-custom').value)||0;
        var rate=('custom'===sel.value)?custom:parseFloat(sel.value);
        var fuel=parseFloat(document.getElementById('c-fuel').value)||0;
        var fuelp=parseFloat(document.getElementById('c-fuelp').value)||0;
        var evMonth=cons*rate*km/100;
        var gasMonth=fuel*fuelp*km/100;
        var diff=gasMonth-evMonth;
        if(km>0&&fuel>0&&fuelp>0){
          dv.style.display='';
          if(diff>0){dv.innerHTML='<div class="c-delta good">Экономия vs бензин: '+Math.round(diff).toLocaleString('ru-RU')+' ₽/мес ('+Math.round(diff*12).toLocaleString('ru-RU')+' ₽/год)</div>';}
          else if(diff<0){dv.innerHTML='<div class="c-delta bad">Бензин дешевле на '+Math.round(-diff).toLocaleString('ru-RU')+' ₽/мес при этих цифрах</div>';}
          else{dv.innerHTML='<div class="c-delta good">Паритет с бензином при этих цифрах</div>';}
        } else {dv.style.display='none';}
      }catch(e){}
    }
    out.addEventListener('DOMSubtreeModified',upd);upd();
    // пресеты-чипсы сцен из select
    var sel=document.getElementById('c-scene');
    if(sel){
      var chips=document.createElement('div');chips.className='c-chips';
      var btns=[];
      Array.prototype.forEach.call(sel.options,function(o){
        if(!o.value) return;
        var b=document.createElement('button');b.type='button';b.textContent=o.textContent.trim();
        if(o.value==='custom') b.textContent='Свой тариф';
        b.dataset.v=o.value;
        if(o.value===sel.value) b.classList.add('on');
        b.addEventListener('click',function(){
          sel.value=b.dataset.v;
          btns.forEach(function(x){x.classList.remove('on')});b.classList.add('on');
          sel.dispatchEvent(new Event('input',{bubbles:true}));
          if(typeof calcR==='function')calcR();
        });
        chips.appendChild(b);btns.push(b);
      });
      sel.parentNode.insertBefore(chips,sel);
      sel.addEventListener('change',function(){Array.prototype.forEach.call(btns,function(x){x.classList.toggle('on',x.dataset.v===sel.value)})});
    }
  }
}catch(e){}});

document.addEventListener('DOMContentLoaded',function(){try{
  ['input','change'].forEach(function(ev){
    document.querySelectorAll('.calc-grid input,.calc-grid select').forEach(function(e){e.addEventListener(ev,calcR)});
  });
  var q=new URLSearchParams(location.search);
  var map={km:'c-km',kwh:'c-cons',m:'c-model',custom:'c-custom',fuel:'c-fuel',fuelp:'c-fuelp'};
  var any=false;
  for(var k in map){var v=q.get(k);if(v){var el=document.getElementById(map[k]);if(el){el.value=v;any=true;}}}
  if(any&&typeof calcR==='function')calcR();
}catch(e){}});
function calcR(){var e=parseFloat(document.getElementById("c-cons").value),t=parseFloat(document.getElementById("c-km").value)||0,n=parseFloat(document.getElementById("c-cap").value)||0,c=document.getElementById("c-scene"),a=parseFloat(document.getElementById("c-custom").value)||0,o="custom"===c.value?a:parseFloat(c.value);document.getElementById("c-cons-v").textContent=e,document.getElementById("c-custom-row").style.display="custom"===c.value?"":"none";var l=e*o,d=l*t/100,u=n*o,m=(parseFloat(document.getElementById("c-fuel").value)||0)*(parseFloat(document.getElementById("c-fuelp").value)||0),s=m*t/100,r=function(e){return Math.round(e).toLocaleString("ru-RU")+" ₽"},v=[["100 км по выбранной сцене",r(l)],["Зарядка в месяц",r(d)],["Полная зарядка от нуля",r(u)],["Бензин: 100 км",r(m)],["Бензин: месяц",r(s)]];document.getElementById("c-out").innerHTML=v.map(function(e){return'<div><div class="k">'+e[0]+'</div><div class="v">'+e[1]+"</div></div>"}).join("");var i="Зарядка моего EV: "+r(l)+" за 100 км, "+r(d)+" в месяц. Посчитай свою: https://zapashoda-ev.ru/calculator/";document.getElementById("c-share").onclick=function(){var p=new URLSearchParams({km:document.getElementById("c-km").value||"0",kwh:document.getElementById("c-cons").value||"0",m:document.getElementById("c-model").value||"",custom:document.getElementById("c-custom").value||"",fuel:document.getElementById("c-fuel").value||"",fuelp:document.getElementById("c-fuelp").value||""});var u="https://zapashoda-ev.ru/calculator/?"+p.toString();var txt="Зарядка моего EV: "+r(d)+" за 100 км, "+r(l)+" в месяц. Посчитай свою: "+u;if(navigator.share){navigator.share({title:"Запас хода — калькулятор зарядки",text:txt,url:u}).catch(function(){});}else if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt);alert("Скопировано: результат со ссылкой на калькулятор");}else{window.open("https://t.me/share/url?url="+encodeURIComponent(u)+"&text="+encodeURIComponent(txt))}}}document.addEventListener("DOMContentLoaded",function(){var e=new URLSearchParams(location.search),t=parseFloat(e.get("km")),n=parseFloat(e.get("kwh")),c=e.get("m");if(t&&(document.getElementById("c-km").value=Math.max(100,Math.round(t/12))),n){var a=document.getElementById("c-cons");a.value=Math.min(25,Math.max(10,n)),document.getElementById("c-cons-v").textContent=a.value}if(c)for(var o=document.getElementById("c-model"),l=c.toLowerCase(),d=0;d<o.options.length;d++)if(-1!==o.options[d].text.toLowerCase().indexOf(l)){o.selectedIndex=d,document.getElementById("c-cap").value=o.value;break}["c-cons","c-km","c-cap","c-scene","c-custom","c-fuel","c-fuelp"].forEach(function(e){document.getElementById(e).addEventListener("input",calcR),document.getElementById(e).addEventListener("change",calcR)}),document.getElementById("c-model").addEventListener("change",function(){this.value&&(document.getElementById("c-cap").value=this.value),calcR()}),calcR()})
;
!function(){function t(){var t=parseFloat(document.getElementById("dt-hour").value)||0,e=parseFloat(document.getElementById("dt-min").value)||0,n=document.getElementById("dt-tow").checked&&parseFloat(document.getElementById("dt-tow-cost").value)||0,d=Math.round(t*(e/60))+n;document.getElementById("dt-loss").textContent=d.toLocaleString("ru-RU")+" ₽",document.getElementById("dt-note").textContent=e>=90?"Полтора часа простоя — уже рабочий день за чужой счёт.":"Каждая минута простоя на станции — это ваши деньги."}document.addEventListener("DOMContentLoaded",function(){["dt-hour","dt-min","dt-tow","dt-tow-cost"].forEach(function(e){var n=document.getElementById(e);n.addEventListener("input",t),n.addEventListener("change",t)}),t()})}()document.addEventListener("DOMContentLoaded",function(){var q=new URLSearchParams(location.search);function set(id,v){if(v)document.getElementById(id).value=v;}set("c-scene",q.get("scene"));set("c-custom",q.get("custom"));set("c-fuel",q.get("fuel"));set("c-fuelp",q.get("fuelp"));var sc=document.getElementById("c-scene");if(sc&&q.get("custom")){sc.value="custom";}var ev=new Event("input");["c-km","c-cons","c-scene","c-custom","c-fuel","c-fuelp"].forEach(function(id){document.getElementById(id).dispatchEvent(ev);});calcR();})
